*{box-sizing:border-box}[hidden]{display:none!important}
#studio{--canvas:#ecefe9;--ink:#24362c;--dim:#526457;--glass:rgba(255,255,251,.81);--paper:#fffef9;--soft:#edf2eb;--edge:#bfcdc1;--peach:#f5b293;--green:#aedc7a;--button:#254d39;--on:#fff;--shade:#374b3716;color-scheme:light;font:15px/1.48 Inter,"Segoe UI",sans-serif;color:var(--ink);min-height:100vh;padding:clamp(14px,3vw,52px);background:radial-gradient(ellipse at 5% 15%,#efbd9a55,transparent 48%),radial-gradient(ellipse at 98% 18%,#abda8759,transparent 44%),var(--canvas)}
#studio.dark{--canvas:#14211d;--ink:#edf5ec;--dim:#bacabb;--glass:rgba(32,47,40,.88);--paper:#1b2a23;--soft:#2c4034;--edge:#506556;--peach:#bd8977;--green:#99bf76;--button:#b5da9e;--on:#173020;--shade:#0003;color-scheme:dark}
header,.grid{max-width:1380px;margin:auto}header,article,.track,.library,.guide{background:var(--glass);border:1px solid var(--edge);border-radius:20px;box-shadow:0 12px 30px var(--shade),inset 0 1px #ffffff30}header{display:flex;justify-content:space-between;align-items:center;padding:16px 22px;margin-bottom:18px;backdrop-filter:blur(10px)}.identity,.actions,.modeRow,nav,.three{display:flex;align-items:center;gap:10px}.logo{background:#264937;color:#c1ea91;padding:7px 13px;border-radius:15px;font-size:30px}
h1,h2,h3,p{margin:0}h1{font-size:clamp(21px,2.3vw,31px);letter-spacing:-.045em}h2{font-size:clamp(24px,2.4vw,33px);letter-spacing:-.045em;margin-bottom:12px}h3{font-size:17px;margin:18px 0 6px}small,.hint,#trackHint{color:var(--dim)}.grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(260px,.86fr);gap:18px;align-items:start}article,.track,.library,.guide{padding:clamp(16px,2.5vw,32px);min-width:0}article{border-top:3px solid var(--peach)}.track,.guide{border-top:3px solid var(--green)}.guide ol{margin:8px 0;padding-left:20px}.guide li{margin:6px 0}.library{margin-top:15px}.library h3{margin-top:0}
button,input,select,textarea{font:inherit;color:inherit}button{cursor:pointer;border-radius:11px;background:var(--soft);border:1px solid var(--edge);padding:8px 14px;font-weight:620;box-shadow:2px 3px 5px var(--shade),inset 1px 1px #ffffff24}button:hover:enabled{border-color:var(--dim)}button:disabled{opacity:.5;cursor:default}button[aria-pressed=true],.primary{background:var(--button);color:var(--on)}button[aria-pressed=true]{box-shadow:inset 1px 2px 4px #0003}.primary{margin-top:16px}.actions .primary{margin:0}.actions,.modeRow,.three{flex-wrap:wrap}.three>label{flex:1;min-width:125px}
nav{color:var(--dim);border-bottom:1px solid var(--edge);margin-bottom:18px;padding-bottom:12px}nav button{box-shadow:none;border:0;background:transparent;padding:4px 8px;font-size:14px}nav [aria-current=step]{color:var(--ink);background:var(--soft)}label{display:block;margin:10px 0;font-weight:600;font-size:14px}input,select,textarea{display:block;width:100%;margin-top:4px;background:var(--paper);border:1px solid var(--edge);padding:9px 11px;border-radius:9px;font-weight:400}textarea{resize:vertical}summary{cursor:pointer;padding:8px 0;font-weight:600}details{margin:8px 0;border-top:1px solid var(--edge)}:focus-visible{outline:3px solid #609e67;outline-offset:2px}.confirm{display:flex;gap:9px;align-items:center}.confirm input{width:auto}.actions{margin:12px 0}.track details{padding:2px 0}.track summary small{display:block;font-weight:400}#usage,#message{white-space:pre-line;overflow-wrap:anywhere}#usage{background:var(--paper);border-radius:10px;padding:13px;margin-bottom:12px}.library button{margin-top:4px}#message:not(:empty){margin-top:15px}#prompt{font:14px/1.55 ui-monospace,monospace}
@media(max-width:760px){.grid{grid-template-columns:minmax(0,1fr)}header{padding:12px}.logo{font-size:22px}.identity{gap:6px}.three{display:block}}
/* Shared studio presentation, identical to the approved Basic design. */
#studio.studioLayout{--canvas:#25342c;--ink:#edf5ec;--dim:#bacabb;--glass:#203028;--paper:#1b2a23;--soft:#2c4034;--edge:#506556;--peach:#bd8977;--green:#99bf76;--button:#b5da9e;--on:#173020;--shade:#0003;color-scheme:dark;background:var(--canvas);position:relative;isolation:isolate;padding:24px;font-size:13px;line-height:1.5}
#studio.studioLayout:not(.dark){--canvas:#e3eadf;--ink:#24362c;--dim:#526457;--glass:#f2f6ed;--paper:#fffef9;--soft:#edf2eb;--edge:#bfcdc1;--peach:#b9876f;--green:#89b666;--button:#254d39;--on:#fff;--shade:#374b3716;color-scheme:light}
#studio.studioLayout::before{content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;opacity:.12;background-image:url("data:image/jpeg;base64,");background-position:center;background-size:cover;background-repeat:no-repeat}
#studio.studioLayout header{padding:14px 18px;margin-bottom:10px;background:var(--glass);border:1px solid var(--edge);border-radius:13px;box-shadow:0 6px 18px var(--shade),inset 0 1px #ffffff20;align-items:center}
#studio.studioLayout .identity{gap:10px;min-width:0}
#studio.studioLayout .logo{display:block;font-size:24px;padding:5px 10px;border-radius:9px}
#studio.studioLayout .identity small{display:block;font-size:10px;line-height:1.4;margin-top:2px}
#studio.studioLayout h1{font-family:Georgia,"Times New Roman",serif;font-size:clamp(22px,2.7vw,34px);letter-spacing:-.035em;line-height:1.1;font-weight:700}
#studio.studioLayout #theme{border-radius:8px;font-size:11px;padding:7px 10px;white-space:nowrap}
#studio.studioLayout #basicToolbar{max-width:1380px;margin:0 auto 12px;display:flex;align-items:center;justify-content:space-between;gap:12px}
#studio.studioLayout .modeRow{gap:7px}
#studio.studioLayout .modeRow button,#studio.studioLayout #reset{font-size:12px;padding:7px 12px;border-radius:8px}
#studio.studioLayout #reset{white-space:nowrap}
#studio.studioLayout .grid{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px}
#studio.studioLayout article,#studio.studioLayout aside{padding:18px;background:var(--glass);border:1px solid var(--edge);border-radius:13px;box-shadow:0 8px 22px var(--shade),inset 0 1px #ffffff20;min-width:0}
#studio.studioLayout article{border-top:3px solid var(--peach)}
#studio.studioLayout aside{border-top:3px solid var(--green)}
#studio.studioLayout h2{font-size:20px;letter-spacing:-.035em;margin-bottom:12px}
#studio.studioLayout h3{font-size:14px;margin:20px 0 10px}
#studio.studioLayout nav{border-bottom:1px solid var(--edge);padding-bottom:10px;margin-bottom:16px;gap:5px}
#studio.studioLayout nav button{font-size:10px;padding:4px 7px}
#studio.studioLayout label{font-size:11px;margin:10px 0}
#studio.studioLayout input,#studio.studioLayout textarea,#studio.studioLayout select{padding:7px 9px;border-radius:7px;margin-top:4px;font-size:12px}
#studio.studioLayout button{border-radius:8px;padding:7px 10px;font-size:11px}
#studio.studioLayout .hint,#studio.studioLayout small{font-size:11px}
#studio.studioLayout details{margin:7px 0}
#studio.studioLayout summary{padding:7px 0;font-size:11px}
#studio.studioLayout #basicTools{display:flex;gap:10px;align-items:center;border:1px solid var(--edge);border-radius:5px;margin-bottom:14px;font-size:10px;line-height:1.6}
#studio.studioLayout #basicTools span{padding:5px 12px;border-right:1px solid var(--edge)}
#studio.studioLayout #basicTools strong{padding:5px 8px 5px 0;font-weight:650}
#studio.studioLayout .actions{gap:6px;flex-wrap:wrap;margin:8px 0}
#studio.studioLayout #prompt{font:11px/1.55 ui-monospace,monospace;min-height:225px;height:225px;border-color:var(--green);box-shadow:0 0 0 1px #99bf7633}
#studio.studioLayout #usage{background:none;border:0;border-radius:0;padding:0;font-size:12px;line-height:1.65;margin:0 0 18px}
#studio.studioLayout #packageNext{margin:0}
#studio.studioLayout #trackPanel,#studio.studioLayout .library,#studio.studioLayout #save{display:none!important}
#studio.studioLayout #message{font-size:11px}
@media(max-width:760px){#studio.studioLayout{padding:16px 14px}#studio.studioLayout header{padding:12px}#studio.studioLayout .grid{grid-template-columns:minmax(0,1fr)}#studio.studioLayout #basicToolbar{flex-wrap:wrap}#studio.studioLayout .modeRow button,#studio.studioLayout #reset{font-size:11px;padding:7px 9px}#studio.studioLayout #basicTools{flex-wrap:wrap;gap:0}#studio.studioLayout #basicTools strong{padding-left:10px}#studio.studioLayout .logo{font-size:20px;padding:5px 8px}}
